const CAPS_SKIP = new Set(['OK', 'PASS', 'FAIL', 'TODO', 'NOTE', 'YES', 'NO', 'AND', 'THE', 'FOR', 'NOT', 'ONE', 'TWO', 'ALL', 'TBD', 'N/A', 'I']);
