const MULTI_RE = /\b[A-Z][a-zA-Z0-9]+(?:[ \-][A-Z][a-zA-Z0-9]+)+\b/g;
const INNER_RE = /\b[A-Za-z]*[a-z][A-Z][A-Za-z0-9]*\b/g;
const ACRO_RE = /\b[A-Z][A-Z0-9]{1,5}s?\b/g;
