  for (const m of s.msgs) {
    if (!isAgent(m.from) || !LIVE_TAG.test(m.tag || '')) continue; // only real model replies
    for (const t of sentences(m.text.replace(SECTION_RE, '\n'))) out.push({ from: m.from, text: t, inPrompt: false });
