interface State {
  mem: Mem; rev: number; storageOk: boolean;
  live: LiveCfg; keys: Partial<Record<ProviderId, string>>; dead: Partial<Record<ProviderId, boolean>>;
  calls: number; tasks: number; tin: number; tout: number; stopped: boolean; busy: boolean; incognito: boolean;
  log: LogMsg[]; viewing: Session | null; active: AgentId | null; pulses: Pulse[]; stages: Partial<Record<AgentId, StageState>>; used: string[];
  status: string; view: View; tab: Tab; selected: string | null; lastRun: RunReport | null; autoRotate: boolean;
  // actions
  commit(fn?: (m: Mem) => void): void;
  setLive(p: Partial<LiveCfg>): void; setKey(k: string): void; forgetKey(): void;
  send(q: string): Promise<void>; stop(): void; testProvider(): Promise<void>;
  runBrain(): void; note(o: { type: EntryType; title: string; note: string }): string | null;
  correct(id: string, fix: { title?: string; note: string }): void; remove(id: string): void;
  setSetting(p: Partial<Mem['settings']>): void; restore(text: string): string; backup(): string; erase(): void;
  select(id: string | null): void; setView(v: View): void; setTab(t: Tab): void; set(p: Partial<State>): void;
  viewSession(id: string | null): void;
}

let logN = 0, pulseN = 0; const ctls = new Set<AbortController>();
const ls: Storage | null = typeof localStorage !== 'undefined' ? localStorage : null;

function loadLive(): { live: LiveCfg; keys: Partial<Record<ProviderId, string>> } {
  const live: LiveCfg = { on: false, provider: 'openai', models: Object.fromEntries(PROVIDERS.map(p => [p, PROV[p].model])) as Record<ProviderId, string>, maxTokens: 120, callCap: 9, remember: false };
  const keys: Partial<Record<ProviderId, string>> = {};
  try {
    const d = JSON.parse(ls?.getItem(LKEY) || 'null');
    if (d && typeof d === 'object') {
      live.remember = !!d.remember; if (d.provider in PROV) live.provider = d.provider;
      if (isFinite(d.maxTokens)) live.maxTokens = Math.max(20, Math.min(150, Math.round(d.maxTokens)));
      if (isFinite(d.callCap)) live.callCap = Math.max(1, Math.min(9, Math.round(d.callCap)));
      for (const p of PROVIDERS) if (typeof d.models?.[p] === 'string' && MODEL_RE.test(d.models[p])) live.models[p] = d.models[p];
    }
    if (live.remember) { const k = JSON.parse(ls?.getItem(LKEYS) || 'null'); if (k && typeof k[live.provider] === 'string') keys[live.provider] = k[live.provider].slice(0, 300); }
  } catch { /* fresh start */ }
  return { live, keys }; // Live AI is always off after a reload
}
function saveLive(live: LiveCfg, keys: Partial<Record<ProviderId, string>>) {
  try {
    ls?.setItem(LKEY, JSON.stringify({ remember: live.remember, provider: live.provider, maxTokens: live.maxTokens, callCap: live.callCap, models: live.models }));
    if (live.remember && keys[live.provider]) ls?.setItem(LKEYS, JSON.stringify({ [live.provider]: keys[live.provider] })); else ls?.removeItem(LKEYS);
  } catch { /* storage blocked */ }
}

const boot = ls ? loadMem(ls) : { mem: blankMem(), ok: false };
{ const t = tally(); maintain(boot.mem, t, Date.now()); } // stale marking uses the real clock
const lv = loadLive();

export const useStore = create<State>()((set, get) => {
  const keyList = () => Object.values(get().keys).filter(Boolean) as string[];
  const clean = (t: string) => redact(t, keyList()).text;
  const say = (m: Msg & { cls?: 'warn' }) => set(s => ({ log: [...s.log, { ...m, text: clean(m.text), id: ++logN }].slice(-200) }));
  const liveReady = () => { const s = get(); return s.live.on && !s.stopped && !!s.keys[s.live.provider] && !s.dead[s.live.provider]; };

  return {
    mem: boot.mem, rev: 0, storageOk: boot.ok, live: lv.live, keys: lv.keys, dead: {}, calls: 0, tasks: 0, tin: 0, tout: 0,
    stopped: false, busy: false, incognito: false, log: [], viewing: null, active: null, pulses: [], stages: {}, used: [],
    status: 'Waiting for a prompt.', view: 'brain', tab: 'activity', selected: null, lastRun: null, autoRotate: true,

    set: p => set(p),
    commit(fn) { const m = get().mem; fn?.(m); const ok = ls ? saveMem(ls, m) : false; set(s => ({ rev: s.rev + 1, storageOk: ok })); },
    setLive(p) { const live = { ...get().live, ...p }; if (p.provider && p.provider !== get().live.provider) { set({ keys: {}, dead: {} }); } set({ live }); saveLive(live, get().keys); },
    setKey(k) { const keys = { [get().live.provider]: k.trim().slice(0, 300) }; set({ keys, dead: {} }); saveLive(get().live, keys); },
    forgetKey() { set({ keys: {} }); saveLive({ ...get().live, remember: false }, {}); set(s => ({ live: { ...s.live, remember: false } })); },

    async send(raw) {
      const s = get(), r = redact(raw.trim(), keyList()), q = r.text;
      if (!q) return set({ status: 'Write a prompt first.' });
      if (r.n) { s.commit(m => { m.filtered += r.n; }); }
      if (!s.live.on) return set({ status: 'Live AI is off. Turn it on in Settings and add a key. Nothing was sent.' });
      if (!s.keys[s.live.provider]) return set({ status: `Add your ${PROV[s.live.provider].label} key in Settings. Nothing was sent.` });
      if (s.dead[s.live.provider]) return set({ status: `${PROV[s.live.provider].label} rejected the key. Reload to try again.` });
      if (s.tasks >= 1) return set({ status: 'One live task per page load. Reload to start another.' });
      if (s.calls >= s.live.callCap) return set({ status: 'The call budget for this page load is used. Reload to reset it.' });
      if (s.busy) return;
      const pv = s.live.provider, model = s.live.models[pv], tag = `live · ${PROV[pv].label} · ${model} · unverified`, color = PROV[pv].color;
