import { MIN_AGE, ageBlockedUntil, blockDevice, dobError, isAdult, type Dob } from './age';

// Local accounts for this browser. There is no server, so this controls who can use the page on this
// device; it is not protection against someone who can open the browser's developer tools or storage.
export const AUTH_KEY = 'brain.auth.v1', SESSION_KEY = 'brain.session.v1';
export const PBKDF2_ITER = 600_000, IDLE_MS = 15 * 60_000, FREE_TRIES = 5, MAX_BACKOFF_MS = 15 * 60_000;
export type Role = 'admin' | 'viewer';
export const ROLE_LABEL: Record<Role, string> = { admin: 'Admin', viewer: 'Viewer' };

export interface User { id: string; name: string; role: Role; salt: string; hash: string; iter: number; created: number; adult: true; addedBy: string | null }
export interface AuthDb { version: 1; users: User[]; fails: number; lockedUntil: number; nextId: number }
type Store = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;

export class AuthError extends Error { constructor(msg: string, public code: 'age' | 'blocked' | 'name' | 'passcode' | 'last-admin' | 'missing' | 'taken' | 'crypto') { super(msg); } }

export const blankAuth = (): AuthDb => ({ version: 1, users: [], fails: 0, lockedUntil: 0, nextId: 1 });
export function loadAuth(s: Store): AuthDb {
  try {
    const d = JSON.parse(s.getItem(AUTH_KEY) || 'null'); if (!d || !Array.isArray(d.users)) return blankAuth();
    const users = (d.users as User[]).filter(u => u && typeof u.id === 'string' && typeof u.name === 'string' && (u.role === 'admin' || u.role === 'viewer') &&
      typeof u.salt === 'string' && typeof u.hash === 'string' && isFinite(u.iter) && u.adult === true);
    return { version: 1, users, fails: Math.max(0, +d.fails || 0), lockedUntil: Math.max(0, +d.lockedUntil || 0), nextId: Math.max(1, +d.nextId || users.length + 1) };
  } catch { return blankAuth(); }
}
export function saveAuth(s: Store, db: AuthDb) { s.setItem(AUTH_KEY, JSON.stringify(db)); }

// ---------- hashing ----------
const enc = new TextEncoder();
const hex = (b: ArrayBuffer | Uint8Array) => Array.from(new Uint8Array(b as ArrayBuffer), x => x.toString(16).padStart(2, '0')).join('');
const unhex = (h: string) => new Uint8Array((h.match(/../g) || []).map(x => parseInt(x, 16)));
function subtle(): SubtleCrypto { const c = globalThis.crypto?.subtle; if (!c) throw new AuthError('This browser cannot hash passcodes here. Open the page in Chrome, Edge, Firefox or Safari from your computer.', 'crypto'); return c; }
export async function hashPasscode(pass: string, saltHex?: string, iter = PBKDF2_ITER): Promise<{ salt: string; hash: string; iter: number }> {
  const salt = saltHex ? unhex(saltHex) : globalThis.crypto.getRandomValues(new Uint8Array(16));
  const key = await subtle().importKey('raw', enc.encode(pass.normalize('NFKC')), 'PBKDF2', false, ['deriveBits']);
  const bits = await subtle().deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: salt as BufferSource, iterations: iter }, key, 256);
  return { salt: hex(salt), hash: hex(bits), iter };
}
function same(a: string, b: string) { if (a.length !== b.length) return false; let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i); return d === 0; }

// ---------- rules ----------
const COMMON = ['passwordpassword', 'password123', '1234567890', 'qwertyuiop', 'letmein123', 'iloveyou123', 'adminadmin', 'brainbrain'];
export const nameError = (n: string) => (/^[A-Za-z0-9][A-Za-z0-9 ._-]{1,31}$/.test(n.trim()) ? null : 'Use 2 to 32 letters, numbers, spaces, dots, dashes or underscores.');
export function passcodeError(p: string, name = ''): string | null {
  if (p.length < 10) return 'Use at least 10 characters.';
  if (p.length > 128) return 'Use 128 characters or fewer.';
  if (new Set(p).size < 4) return 'Use a mix of different characters.';
  const low = p.toLowerCase();
  if (name.trim().length >= 3 && low.includes(name.trim().toLowerCase())) return 'Do not put your name in the passcode.';
  if (COMMON.some(c => low.includes(c))) return 'That passcode is too easy to guess.';
  return null;
}
export const adminCount = (db: AuthDb) => db.users.filter(u => u.role === 'admin').length;
export const needsSetup = (db: AuthDb) => db.users.length === 0;

/** Add an account. The date of birth is checked here and never stored. Under 18: refused, and this browser refuses new accounts for a day. */
export async function createUser(db: AuthDb, store: Store, input: { name: string; role: Role; passcode: string; dob: Dob }, ctx: { now: number; addedBy: string | null; iter?: number }): Promise<User> {
  const wait = ageBlockedUntil(store, ctx.now);
  if (wait) throw new AuthError('New accounts are paused on this browser. Try again later.', 'blocked');
  const bad = dobError(input.dob, ctx.now);
  if (bad) throw new AuthError(bad, 'age');
  if (!isAdult(input.dob, ctx.now)) { blockDevice(store, ctx.now); throw new AuthError(`Brain is for adults only (${MIN_AGE}+). No account was made.`, 'age'); }
  const name = input.name.trim(), e1 = nameError(name); if (e1) throw new AuthError(e1, 'name');
  if (db.users.some(u => u.name.toLowerCase() === name.toLowerCase())) throw new AuthError('That name is already used.', 'taken');
  const e2 = passcodeError(input.passcode, name); if (e2) throw new AuthError(e2, 'passcode');
  const h = await hashPasscode(input.passcode, undefined, ctx.iter);
  const u: User = { id: 'u' + db.nextId++, name, role: input.role, ...h, created: ctx.now, adult: true, addedBy: ctx.addedBy };
  db.users.push(u); saveAuth(store, db); return u;
}

export const backoffMs = (fails: number) => (fails < FREE_TRIES ? 0 : Math.min(MAX_BACKOFF_MS, 30_000 * 2 ** (fails - FREE_TRIES)));
export type LoginResult = { ok: true; user: User } | { ok: false; reason: 'wrong' | 'locked'; waitMs: number };
/** Check a name and passcode. Too many misses slow the next try down (30 s, then doubling, up to 15 min). */
export async function verifyLogin(db: AuthDb, store: Store, name: string, pass: string, now: number): Promise<LoginResult> {
  if (db.lockedUntil > now) return { ok: false, reason: 'locked', waitMs: db.lockedUntil - now };
  const u = db.users.find(x => x.name.toLowerCase() === name.trim().toLowerCase());
  const h = await hashPasscode(pass, u?.salt ?? '00'.repeat(16), u?.iter ?? PBKDF2_ITER); // same work whether or not the name exists
  if (u && same(h.hash, u.hash)) { db.fails = 0; db.lockedUntil = 0; saveAuth(store, db); return { ok: true, user: u }; }
  db.fails++; const w = backoffMs(db.fails); db.lockedUntil = w ? now + w : 0; saveAuth(store, db);
  return { ok: false, reason: 'wrong', waitMs: w };
}

// ---------- admin actions ----------
export function removeUser(db: AuthDb, store: Store, id: string) {
  const u = db.users.find(x => x.id === id); if (!u) throw new AuthError('No such account.', 'missing');
  if (u.role === 'admin' && adminCount(db) <= 1) throw new AuthError('Brain needs at least one admin.', 'last-admin');
  db.users = db.users.filter(x => x.id !== id); saveAuth(store, db);
}
export async function setPasscode(db: AuthDb, store: Store, id: string, pass: string, iter?: number) {
  const u = db.users.find(x => x.id === id); if (!u) throw new AuthError('No such account.', 'missing');
  const e = passcodeError(pass, u.name); if (e) throw new AuthError(e, 'passcode');
  Object.assign(u, await hashPasscode(pass, undefined, iter)); saveAuth(store, db);
}

// ---------- session: this tab only, locks after 15 idle minutes ----------
export function startSession(s: Store, u: User, now: number) { s.setItem(SESSION_KEY, JSON.stringify({ uid: u.id, exp: now + IDLE_MS })); }
export function readSession(s: Store, db: AuthDb, now: number): User | null {
  try { const d = JSON.parse(s.getItem(SESSION_KEY) || 'null'); const u = d && db.users.find(x => x.id === d.uid); if (u && d.exp > now) return u; } catch { /* no session */ }
  s.removeItem(SESSION_KEY); return null;
}
export const touchSession = (s: Store, now: number) => { try { const d = JSON.parse(s.getItem(SESSION_KEY) || 'null'); if (d) { d.exp = now + IDLE_MS; s.setItem(SESSION_KEY, JSON.stringify(d)); } } catch { /* ignore */ } };
export const endSession = (s: Store) => s.removeItem(SESSION_KEY);
