// Live chat for viewers. The admin's tab publishes what it shows; a viewer tab in the same browser mirrors it.
// There is no server, so this only reaches other tabs or windows on the same computer and browser.
import type { LogMsg, Pulse, StageState } from '../store';
import type { AgentId } from '../data/team';

export const CHANNEL = 'brain.live.v1';
export type Wire =
  | { t: 'hello' }
  | { t: 'reset'; stages: Partial<Record<AgentId, StageState>>; notes: Partial<Record<AgentId, string>>; status: string }
  | { t: 'msg'; m: LogMsg }
  | { t: 'stage'; stages: Partial<Record<AgentId, StageState>>; notes: Partial<Record<AgentId, string>>; active: AgentId | null; busy: boolean; status: string }
  | { t: 'pulse'; p: Omit<Pulse, 't0'> }
  | { t: 'snapshot'; log: LogMsg[]; stages: Partial<Record<AgentId, StageState>>; notes: Partial<Record<AgentId, string>>; active: AgentId | null; busy: boolean; status: string };

export interface Chan { postMessage(d: unknown): void; onmessage: ((e: { data: unknown }) => void) | null; close(): void }
export interface Live { log: LogMsg[]; stages: Partial<Record<AgentId, StageState>>; notes: Partial<Record<AgentId, string>>; active: AgentId | null; busy: boolean; status: string; pulses: Pulse[] }
