import type { Session } from '../lib/memory';
import { useStore, type StageState } from '../store';

const MARK: Record<StageState, string> = { waiting: '○', working: '◉', done: '✓', failed: '✕', skipped: '–' };
const WORD: Record<StageState, string> = { waiting: 'waiting', working: 'working', done: 'covered', failed: 'failed', skipped: 'skipped' };

export interface Cov { states: Partial<Record<AgentId, StageState>>; notes: Partial<Record<AgentId, string>> }
export function fromSession(s: Session): Cov {
