    for (let j = 0; j < TRAIL; j++) { const u = t - j * 0.018; setDot(dots, j, at(u), col, 0.13 - j * 0.0065, t <= 1 && u >= 0 ? (1 - j / TRAIL) * 0.95 : 0); }
