}
/** How far a point is from the brain: negative means it is inside the brain. Outline units. */
export function brainClearance([x, y, z]: P3) { const hw = halfWidth(x, y); return hw > 0 ? Math.abs(z) - hw : Infinity; }

export interface Skull { positions: Float32Array; index: Uint32Array; count: number; dropped: number; edge: P2[]; reentries: number }
/** The skull as one closed shell (both sides), with an opening where the brainstem passes. World units. */
export function buildSkull(): Skull {
  const { arc, rings, clear } = SKULL, edge: P2[] = []; let reentries = 0;
  for (let i = 0; i < arc; i++) {
    const th = (2 * Math.PI * i) / arc, dx = Math.cos(th), dy = Math.sin(th);
    let t = 0; while (t < 1400 && sdSkull(HUB.x + dx * t, HUB.y + dy * t) > 0) t += 3;
    let lo = Math.max(0, t - 3), hi = t; for (let k = 0; k < 18; k++) { const m = (lo + hi) / 2; if (sdSkull(HUB.x + dx * m, HUB.y + dy * m) > 0) lo = m; else hi = m; }
    edge.push([HUB.x + dx * lo, HUB.y + dy * lo]);
    for (let u = hi + 6; u < 1400; u += 6) if (sdSkull(HUB.x + dx * u, HUB.y + dy * u) > 0) { reentries++; break; }
  }
  const pts: P3[] = [], idx: number[] = []; let dropped = 0;
  for (const side of [-1, 1]) {
    const base = pts.length;
    for (let r = 0; r <= rings; r++) {
      const t = 1 - Math.pow(1 - r / rings, 1.5);
      for (let i = 0; i < arc; i++) { const x = HUB.x + (edge[i][0] - HUB.x) * t, y = HUB.y + (edge[i][1] - HUB.y) * t; pts.push([x, y, r === rings ? 0 : side * skullWidth(x, y)]); }
    }
    for (let r = 0; r < rings; r++) for (let i = 0; i < arc; i++) {
      const a = base + r * arc + i, b = base + r * arc + ((i + 1) % arc), c = a + arc, d = b + arc;
      for (const tri of side > 0 ? [[a, c, b], [b, c, d]] : [[a, b, c], [b, d, c]]) {
        if (tri.some(v => brainClearance(pts[v]) < clear)) { dropped++; continue; } // never pass through the brain
        idx.push(...tri);
      }
    }
  }
  const positions = new Float32Array(pts.length * 3); pts.forEach((p, k) => positions.set(toWorld(p), k * 3));
  return { positions, index: new Uint32Array(idx), count: pts.length, dropped, edge, reentries };
}

/** Thin detail lines of the face: eye sockets, nose opening, cheekbones, teeth line, jaw. Outline units, then world. */
export function skullLines(): P3[][] {
  const out: P3[][] = [], P = (dx: number, dy: number, zmm: number): P3 => [...at(dx, dy), zmm * MM];
  const curve = (f: (u: number) => [number, number, number], n = 24) => Array.from({ length: n + 1 }, (_, k) => P(...f(k / n)));
  for (const s of [-1, 1]) {
    out.push(curve(u => { const a = 2 * Math.PI * u, z = 32 + 20 * Math.cos(a); return [4 + 10 * ((z - 12) / 40) ** 2, 18 + 17.5 * Math.sin(a), s * z]; }, 40)); // eye socket rim
    out.push(curve(u => [-2 + 6 * u, 24 + 28 * u, s * 12 * Math.sin(Math.PI * u)])); // nose opening
    out.push(curve(u => [22 + 50 * u, 40 - 3 * Math.sin(Math.PI * u), s * (60 + 6 * Math.sin(Math.PI * Math.min(1, u * 1.3)))])); // cheekbone arch to the ear
    out.push(curve(u => [10 + 20 * u, 52 - 8 * u, s * (40 + 23 * u)], 12)); // lower edge of the cheekbone
    out.push(curve(u => [-3 + 48 * u, 76 - 4 * u, s * 28 * Math.sin(Math.PI / 2 * u)])); // upper teeth line
    out.push(curve(u => [-1 + 46 * u, 78 + 2 * u, s * 27 * Math.sin(Math.PI / 2 * u)])); // lower teeth line
    out.push(curve(u => { const a = 1 - u; return [8 + 77 * a, 120 - 20 * a * a, s * (49 * Math.sin(Math.PI / 2 * a))]; })); // lower border of the jaw
    out.push(curve(u => [72 + 13 * u, 40 + 60 * u, s * (50 - u)], 12)); // back of the jaw (ramus)
  }
  return out.map(l => l.map(toWorld));
}
