export function parseReply(provider: ProviderId, data: any): CallResult {
  if (provider === 'anthropic') return { text: (data.content || []).filter((c: any) => c.type === 'text').map((c: any) => c.text).join(''), why: data.stop_reason || '',
    tin: +(data.usage?.input_tokens) || 0, tout: +(data.usage?.output_tokens) || 0 };
  if (provider === 'google') { const c = (data.candidates || [])[0] || {};
    return { text: (c.content?.parts || []).map((p: any) => p.text || '').join(''), why: c.finishReason || data.promptFeedback?.blockReason || '',
      tin: +(data.usageMetadata?.promptTokenCount) || 0, tout: +(data.usageMetadata?.candidatesTokenCount) || 0 }; }
  let text = typeof data.output_text === 'string' ? data.output_text : '';
  if (!text) text = (data.output || []).flatMap((it: any) => it.content || []).filter((c: any) => c && typeof c.text === 'string' && (!c.type || c.type === 'output_text')).map((c: any) => c.text).join('');
  return { text, why: data.incomplete_details?.reason || '', tin: +(data.usage?.input_tokens) || 0, tout: +(data.usage?.output_tokens) || 0 };
}

