{"stdout":"export async function callModel(o: CallOpts): Promise<CallResult> {
  const req = buildRequest(o, !!o.onDelta), ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), o.timeoutMs ?? 30000);
  const onStop = () => ctl.abort(); o.signal?.addEventListener('abort', onStop);
  let res: Response, raw = '', streamed: CallResult | null = null;
  try {
    res = await (o.fetchImpl || fetch)(req.url, { method: 'POST', headers: req.headers, body: JSON.stringify(req.body), signal: ctl.signal });
    if (res.ok && o.onDelta && res.body && /event-stream/i.test(res.headers.get('content-type') || '')) streamed = await readStream(o.provider, res, o.onDelta, o.key);
    else raw = await res.text();
  }
  catch (e: any) {
    throw new ProviderError(o.signal?.aborted ? 'stopped by you' : e?.name === 'AbortError' ? 'no answer after 30 seconds'
      : 'the browser blocked the call (open index.html from your computer and check your internet)');
  } finally { clearTimeout(timer); o.signal?.removeEventListener('abort', onStop); }
  if (streamed) return streamed;
  if (!res.ok) {
    const rejected = res.status === 401 || res.status === 403 || (o.provider === 'google' && res.status === 400 && /API key not valid|API_KEY_INVALID/i.test(raw));
    throw new ProviderError(httpMessage(res.status, raw, o.key) + (rejected ? ' (key rejected; this provider is off until you reload)' : ''), rejected);
  }
  let data: unknown; try { data = JSON.parse(raw); } catch { throw new ProviderError('the reply was not JSON'); }
  return parseReply(o.provider, data);
}
