      {times.length > 0 && <div className="ftimes">{times.map(id => <span key={id} style={{ '--c': colorOf(id) } as CSSProperties}><b className="sw8" />{AGENT[id].name} {(ms![id]! / 1000).toFixed(1)} s</span>)}</div>}
    </section>
