import { extractSession } from './extract';
import {
  STALE_DAYS,
  MAX_ENTRIES,
  byId,
  byKey,
  link,
  mkEntry,
  type Entry,
  type EntryType,
  type Mem,
  type Session,
  type Source,
} from './memory';
import { redact } from './redact';

export interface Tally {
  fresh: number;
  reinforced: number;
  updated: number;
  stale: number;
  blocked: number;
  touched: Set<string>;
  changed: string[];
}
export const tally = (): Tally => ({
  fresh: 0,
  reinforced: 0,
  updated: 0,
  stale: 0,
  blocked: 0,
  touched: new Set(),
  changed: [],
});

function addSource(e: Entry, s: Source) {
  if (e.sources.some(x => x.kind === s.kind && x.label === s.label && x.ref === (s.ref || null))) return;
  e.sources.push({ kind: s.kind, label: s.label, ref: s.ref || null });
  if (e.sources.length > 6) e.sources.shift();
}
function mergeNote(fresh: string, old: string) {
  const lines = [...new Set([...fresh.split('\n'), ...old.split('\n')].map(l => l.trim()).filter(Boolean))];
  return clip(lines.join('\n'), 600);
}

interface Spec {
  key: string;
  type: EntryType;
  title: string;
  note: string;
  sources: Source[];
  kws?: string[];
}
/** Write or refresh one entry. A key Owner deleted is never learned again. */
export function upsert(m: Mem, spec: Spec, t: Tally, now: number): Entry | null {
  if (m.blocked.includes(spec.key)) {
    t.blocked++;
    return null;
  }
  let e = byKey(m, spec.key);
  if (e && t.touched.has(e.id)) {
    spec.sources.forEach(s => addSource(e!, s));
    return e;
  }
  if (!e) {
    if (m.entries.length >= MAX_ENTRIES) {
      t.blocked++;
      return null;
    }
    e = mkEntry(m, spec, now);
    m.entries.push(e);
    t.fresh++;
  } else {
    const wasStale = e.status === 'stale';
    e.strength = Math.min(9, e.strength + 1);
    e.seen = now;
    e.status = 'fresh';
    spec.sources.forEach(s => addSource(e!, s));
    if (spec.kws) e.kws = [...new Set([...(spec.kws || []), ...(e.kws || [])])].slice(0, 12);
    const merged = e.corrected ? e.note : mergeNote(spec.note, e.note);
    if (merged !== e.note) {
      e.note = merged;
      t.updated++;
    } else if (wasStale) t.updated++;
    else t.reinforced++;
  }
  t.touched.add(e.id);
  t.changed.push(e.id);
  return e;
}

function findWorkstream(m: Mem, kws: string[]): Entry | undefined {
  let best: { e: Entry; ov: number } | undefined;
  for (const e of m.entries) {
    if (e.type !== 'workstream' || !e.kws) continue;
    const ov = e.kws.filter(k => kws.includes(k)).length;
    if (ov >= Math.min(3, e.kws.length, kws.length) && ov > 0 && (!best || ov > best.ov)) best = { e, ov };
  }
  return best?.e;
}

/** Learn one saved session: its workstream, the concepts and entities in it, and how they connect. */
export function learnSession(m: Mem, s: Session, t: Tally, now: number) {
  const ex = extractSession(s, { instructions: m.settings.instructions });
  const src: Source = { kind: 'session', label: `Session ${fmtDate(s.ts)}: ${clip(s.q, 48)}`, ref: s.id };
  const existing = findWorkstream(m, ex.workstream.kws);
  const ws = upsert(
    m,
    {
      key: existing ? existing.key : 'ws:' + s.id,
      type: 'workstream',
      title: existing ? existing.title : ex.workstream.title,
      note: ex.workstream.note,
      kws: ex.workstream.kws,
      sources: [src],
    },
    t,
    now,
  );
  const made = new Map<string, Entry>();
  for (const tp of ex.topics) {
    const note = tp.snippets.map(sn => `${sn.from}: ${sn.text}`).join('\n');
    const e = upsert(m, { key: tp.key, type: tp.type, title: tp.title, note, kws: tp.kws, sources: [src] }, t, now);
    if (e) {
      made.set(tp.key, e);
      if (ws) link(ws, e);
    }
  }
  for (const [a, b] of ex.pairs) link(made.get(a), made.get(b));
  for (const id of s.used || []) if (ws) link(ws, byId(m, id));
  s.learned = true;
}

