import { session } from './fixtures';

describe('learning', () => {
  it('writes linked entries that point back to their session', () => {
    const m = blankMem(),
      s = session();
    m.sessions.push(s);
    const t = tally();
    learnSession(m, s, t, s.ts);
    expect(t.fresh).toBeGreaterThan(3);
    const ws = m.entries.find(e => e.type === 'workstream')!;
    expect(ws.sources[0]).toMatchObject({ kind: 'session', ref: 's1' });
    expect(ws.links.length).toBe(m.entries.length - 1);
    expect(m.entries.every(e => e.sources.some(x => x.ref === 's1'))).toBe(true);
    expect(s.learned).toBe(true);
  });
  it('reinforces a topic that comes back in a later session', () => {
    const m = blankMem(),
      a = session('s1'),
      b = session('s2', a.ts + DAY);
    m.sessions.push(a, b);
    learnSession(m, a, tally(), a.ts);
    const before = byKey(m, 'concept:memory graph')!.strength;
    learnSession(m, b, tally(), b.ts);
    const e = byKey(m, 'concept:memory graph')!;
    expect(e.strength).toBe(before + 1);
    expect(e.sources.map(x => x.ref)).toEqual(expect.arrayContaining(['s1', 's2']));
    expect(m.entries.filter(x => x.type === 'workstream').length).toBe(1); // same task joins the same workstream
  });
  it('marks entries stale after 30 days on the real clock and refreshes them when seen again', () => {
    const m = blankMem(),
      s = session();
    learnSession(m, s, tally(), s.ts);
    const t = tally();
    maintain(m, t, s.ts + 31 * DAY);
    expect(t.stale).toBe(m.entries.length);
    const again = session('s2', s.ts + 32 * DAY);
    learnSession(m, again, tally(), again.ts);
    expect(byKey(m, 'concept:memory graph')!.status).toBe('fresh');
  });
  it('keeps a correction and never relearns a deleted entry', () => {
    const m = blankMem(),
      s = session();
    learnSession(m, s, tally(), s.ts);
    const e = byKey(m, 'concept:memory graph')!;
    correctEntry(m, e.id, { note: 'Owner says: the graph is the main view.' }, s.ts + 1);
    const ent = byKey(m, 'entity:react')!;
    deleteEntry(m, ent.id);
    const s2 = session('s2', s.ts + DAY);
    learnSession(m, s2, tally(), s2.ts);
    expect(byKey(m, 'concept:memory graph')!.note).toBe('Owner says: the graph is the main view.');
    expect(byKey(m, 'entity:react')).toBeUndefined();
    expect(m.blocked).toContain('entity:react');
  });
