    const m = blankMem(),
      s = session();
    s.learned = false;
    m.sessions.push(s);
    addNote(m, { type: 'concept', title: 'Owner prefers plain words', note: 'Short sentences on the page.' }, s.ts);
    const r = brainRun(m, s.ts + 10);
    expect(r.sessions).toBe(1);
